from pathlib import Path
p=Path('emotion_ui.js');s=p.read_text(encoding='utf-8')
def replace(name,nextname,value):
 global s
 a=s.index('function '+name+'(');b=s.index('function '+nextname+'(',a);s=s[:a]+value+'\n'+s[b:]
replace('erFresh','erRows',r'''function erFresh(m){if(!m)return false;if(m.suspended_current)return (erModel().at||'').slice(0,10)===new Date(Date.now()+8*3600000).toISOString().slice(0,10);if(!m.valid)return false;return mtSnapshotFresh({mode:m.mode==='盘中暂态'?'连续竞价':m.mode,valid_until:m.valid_until});}''')
replace('erHeight','erRankCell',r'''function erHeight(m){if(m.suspended_current)return m.height+'板 · 停牌保留';if(m.height==null)return '板位待核验';var h=(m.height_exact?'':'至少')+m.height+'板';return m.sealed?h+(m.mode==='正式收盘'?' · 收盘确认':' · 在板待收盘'):(m.prior_height||0)+'板 · 前日完成';}''')
replace('erTable','erMetric',r'''function erTable(rows){return '<div class="tw"><table class="market-strength-table er-table"><thead><tr><th class="l">个股 / 确认方向</th><th>身位 / 当前状态</th><th class="l">地位与事件</th><th class="l">关系依据</th><th>今日涨幅 / 换手</th><th>实际源时间</th></tr></thead><tbody>'+rows.map(function(r){var m=r.emotion_relay||{},links=(m.continuation||[]).map(function(n){return '<p class="er-connection">'+esc(n.label)+' · '+esc(n.leader_name)+'<span class="cd">节点 / 本股首板 '+esc(n.first_board_date)+' · '+esc(n.board)+'</span></p>';}).join('')+(m.companions||[]).map(function(n){return '<p class="er-connection">伴生参照 '+esc(n.leader_name)+'<span class="cd">本股启动 '+esc(n.start)+' · 同步封板 '+n.overlap_days.length+'日</span></p>';}).join('');return '<tr data-relay-code="'+esc(r.code)+'" class="clickable" onclick="showStock(\''+jsq(r.code)+'\')"><td class="l"><b>'+esc(r.name)+'</b><span class="cd">'+r.code+'</span>'+msAffiliation(r,'emotion')+'</td><td><b class="er-position">'+esc(erHeight(m))+'</b><span class="cd">'+(m.suspended_current?'最后成交 '+esc(m.last_trade_date)+' · '+fmt(m.price,2)+'元':'前一完成日 '+esc(m.prior_date||'—')+' · '+(m.prior_height==null?'待核验':m.prior_height+'板'))+'</span></td><td class="l"><div class="ms-tag-list">'+erTags(m)+'</div>'+(m.reason?'<span class="cd">'+esc(m.reason)+'</span>':'')+'</td><td class="l">'+(links||(m.relations||[]).slice(0,2).map(function(b){return '<p>'+esc(b.name)+' '+msTag(b.state,'排除本股有效同行 '+b.valid+'/'+b.expected+'；在板 '+b.limit_count+'只')+'<span class="cd">在板 '+b.limit_count+' · 覆盖 '+fmt(b.coverage_pct,1)+'%</span></p>';}).join(''))+'</td><td>'+(m.suspended_current?'<span class="ms-muted">全天停牌</span>':pctHtml(m.feedback_pct,2)+'<span class="cd">换手 '+fmt(m.turnover_pct,2)+'%</span>')+'</td><td><span class="cd">'+esc(m.suspended_current?m.last_trade_date+'（最后成交）':m.quote_at||'待更新')+'</span>'+esc(m.suspended_current?'停牌公告已核验':m.mode||'')+'</td></tr>';}).join('')+'</tbody></table></div>';}''')
replace('renderEmotion','erPut',r'''function renderEmotion(){var host=document.getElementById('emotion-host'),meta=erModel();if(!host)return;if(!meta){host.innerHTML='<section class="card">正在等待接力数据。</section>';return;}var focus=document.activeElement;if(focus&&host.contains(focus)&&(focus._msComposing||focus._msEnding))return;var v=MS_VIEW.emotion,rows=erRows(),fb=meta.yesterday_feedback||{},c=meta.coverage||{},cy=meta.cycles||{},dc=cy.disclosure_coverage||{},formal=meta.mode==='正式收盘',live=erLive();document.getElementById('emotion-sub').textContent=meta.scope+' · '+meta.mode+' · 行情截至 '+(meta.source_at||'待更新');
 var h='<div class="er-context"><div><span class="er-eyebrow">周期 · 高度 · 接续</span><h2>'+esc(meta.state)+'</h2><p>周期核心保留停牌前高度，当前在板和节点首板批次分别观察。</p></div><button class="btn" onclick="goPane(\'boards\')">板块／题材</button></div><div class="er-metrics">'+erMetric('近期周期最高标',(cy.cycle_highest||0)+'板','完成高度 · 含已核验停牌核心')+erMetric(formal?'当日收盘最高':live?'当前在板最高':'上次在板最高（待更新）',meta.highest_live+'板',formal?'正式收盘确认':'盘中晋级，待收盘')+erMetric('前一完成日在交易高标',meta.highest_previous+'板','不含当日停牌；实际截至 '+esc(meta.prior_history_asof||meta.history_asof))+erMetric('昨日封板股晋级',fmt(fb.promotion_pct,1)+'%',fb.sealed+'/'+fb.valid+'有效 · 队列 '+fb.expected)+'</div>';
 h+='<section class="card er-cycle"><div class="er-section-heading"><h3>近期周期核心</h3><span>已完成至少5板 · 最近5个交易日仍有封板记录</span></div><div class="er-core-grid">'+(cy.cores||[]).map(function(x){return '<button class="er-core" onclick="showStock(\''+jsq(x.code)+'\')"><span>'+esc(x.name)+' <small>'+x.code+'</small></span><b>'+x.height+'板'+(x.suspended?' · 停牌保留':'')+'</b><small>本轮 '+esc(x.start)+' — '+esc(x.last)+'<br>最后封板后'+(x.end?'于 '+esc(x.end)+' 断板':'尚未确认断板')+'</small></button>';}).join('')+'</div><p class="ms-muted">停牌不按断板处理、不增加板数，也不计入当日在板和晋级分母。以上为近期周期定位，不宣称唯一市场龙头。</p></section>';
 h+='<div class="er-dual"><section class="card"><div class="er-section-heading"><h3>前一完成日封板梯队</h3><span>'+esc(meta.prior_history_asof||meta.history_asof)+'</span></div>'+erLadder(meta.daily_ladder)+'</section><section class="card"><div class="er-section-heading"><h3>'+(formal?'收盘梯队':'当前在板梯队')+'</h3><span>'+esc(meta.mode)+'</span></div>'+erLadder(meta.live_ladder)+'</section></div>';
 h+='<section class="card"><div class="er-section-heading"><h3>分板位晋级与负反馈</h3><span>有效分母与缺口分别显示</span></div><div class="er-promotion">'+(meta.promotion||[]).map(function(p){return '<div><b>'+p.height+'→'+(p.height+1)+'板</b><strong>'+fmt(p.promotion_pct,1)+'%</strong><small>'+p.sealed+'/'+p.valid+'有效 · 应跟踪 '+p.expected+' · 中位 '+pctHtml(p.median_return_pct,2)+'</small></div>';}).join('')+'</div><p class="ms-muted">昨日断板队列 '+meta.broken_feedback.expected+'只 · 今日有效 '+meta.broken_feedback.valid+'只 · 中位反馈 '+pctHtml(meta.broken_feedback.median_return_pct,2)+' · 明显负反馈 '+meta.broken_feedback.large_loss_count+'只。</p></section>';
 h+='<section class="card er-candidates"><div class="er-section-heading"><h3>龙头与接续观察</h3><span>节点、首板日期和后续强度一起看</span></div>'+msDirectionPicker('emotion')+'<div class="ms-toolbar">'+msSelect('scope',[['all','全部接力事件'],['leaders','高标 / 同身位'],['continuation','节点接续候选'],['companions','伴生关系观察'],['suspended','停牌核心'],['sealed','当前在板'],['broken','断板反馈'],['pending','数据待核验']],'emotion','接力观察范围')+'<input aria-label="情绪股票搜索" placeholder="代码 / 名称" value="'+esc(v.q)+'" data-ms-search-key="emotion" data-ms-search-field="q" oninput="msSearchInput(event,this,\'emotion\',\'q\')"><button class="btn" onclick="erCSV()">导出当前观察</button></div><p class="ms-muted">当前 '+rows.length+'只。断板补涨取最高标断板当日首板；监管与停牌各建节点，共享确认题材后跟踪原批次，谁最终走强由后续决定。催化与因果单独待核验。</p>'+erTable(rows.slice(0,v.limit))+(rows.length>v.limit?'<button class="btn" onclick="MS_VIEW.emotion.limit+=100;renderEmotion()">加载更多</button>':'')+'</section>';
 h+='<details class="card er-data"><summary>最近'+meta.history_days+'个交易日完整复核</summary><p>'+esc(meta.history_from)+' — '+esc(meta.history_asof)+' · <button class="btn" onclick="erTimelineCSV()">导出逐日概况</button></p><div class="tw"><table class="market-strength-table"><thead><tr><th>交易日</th><th>已核验 / 应覆盖</th><th>收盘封板</th><th>交易高标</th><th>含停牌保留高度</th><th>全天停牌</th><th>待核验</th></tr></thead><tbody>'+(meta.timeline||[]).map(function(t){return '<tr><td>'+t.date+'</td><td>'+t.valid+'/'+t.expected+'</td><td>'+t.limit_count+'</td><td>'+(t.highest||0)+'板</td><td>'+(t.retained_highest||0)+'板</td><td>'+t.suspended+'</td><td>'+t.unknown+'</td></tr>';}).join('')+'</tbody></table></div><p>普通10%制度主板池 '+c.pool+'只 · 有效报价 '+c.valid_quotes+' · 最近完成日可核验 '+c.valid_history+'。原价OHLC、每日涨跌额反推的参考前收交叉核验；有公告证据的全天停牌保留链，未知不填成未涨停。</p><p>公告焦点股票覆盖 '+dc.covered+'/'+dc.expected+'；非全市场公告扫描。指数偏离仅展示未处理公告重置的滚动参考，正式异动以公司与交易所披露为准，不推断自动停牌或躲异动动机。</p><p>'+meta.limitations.map(esc).join('；')+'。</p><p>规则 '+esc(meta.version)+' · UI '+esc(DATA.ui_generation||'')+'</p></details>';
 erPut(host,h,focus,['情绪股票搜索','搜索板块题材']);}
function erTimelineCSV(){var fields=['date','valid','expected','limit_count','highest','retained_highest','suspended','unknown'],headers=['交易日','已核验','应覆盖','收盘封板','交易高标','含停牌保留高度','全天停牌','待核验','UI版本'];downloadMSCSV('\ufeff'+headers.join(',')+'\n'+(erModel().timeline||[]).map(function(t){return fields.map(function(k){return t[k];}).concat(DATA.ui_generation).join(',');}).join('\n'),'情绪20日概况_'+DATA.ui_generation+'.csv');}''')
replace('erStockDetail','erOverview',r'''function erStockDetail(m){if(!m)return '';var reg=m.regulation||{},ref=reg.reference||{};return '<details class="card er-stock-detail"><summary>主板龙头接力依据 · '+esc(erHeight(m))+'</summary><p>'+esc(m.suspended_current?'最后成交 '+m.last_trade_date:m.mode+' · '+m.quote_at)+'</p><div class="ms-tag-list">'+erTags(m)+'</div>'+(m.continuation||[]).map(function(n){return '<p><b>'+esc(n.label)+'</b> · '+esc(n.leader_name)+'，节点 '+esc(n.date)+'，本股同日首板。公开时间 '+esc(n.known_at)+'；共享题材 '+n.boards.map(function(b){return esc(b.name);}).join('、')+'。'+esc(n.basis)+'</p>';}).join('')+(m.companions||[]).map(function(n){return '<p>伴生参照 '+esc(n.leader_name)+'：核心启动 '+esc(n.core_start)+'，本股 '+esc(n.start)+'；同步封板 '+n.overlap_days.map(esc).join('、')+'。'+esc(n.basis)+'</p>';}).join('')+'<h4>异动与停复牌披露</h4><p class="ms-muted">'+(reg.covered?'已扫描焦点股票的近期公告。':'近期公告尚未覆盖，不能据此判断无监管风险。')+'</p>'+(reg.notices||[]).map(function(n){return '<p><a href="'+esc(n.pdf_url||n.url)+'" target="_blank" rel="noopener noreferrer">'+esc(n.title)+'</a><span class="cd">实际公开 '+esc(n.published_at)+' · 首个可交易日 '+esc(n.available_day||'待核验')+'</span></p>';}).join('')+'<h4>分类指数偏离滚动参考</h4><p class="ms-muted">'+esc(ref.basis||'必要窗口待核验')+'。'+esc(ref.benchmark||'')+'；阈值差不是可继续上涨的额度。</p>'+(ref.windows||[]).map(function(w){return '<p>'+w.days+'交易日 · 截至 '+esc(w.asof)+' · '+(w.deviation_pp==null?esc(w.reason):'偏离 '+w.deviation_pp+'个百分点 / 上涨阈值 '+w.threshold_pp+'个百分点')+'</p>';}).join('')+'<h4>最近20个完成交易日</h4><div class="tw"><table class="market-strength-table"><thead><tr><th>日期</th><th>原价收盘</th><th>封板 / 停牌</th><th>完成高度</th><th>核验</th></tr></thead><tbody>'+(m.history||[]).map(function(p){return '<tr><td>'+p.date+'</td><td>'+fmt(p.close,2)+'</td><td>'+(p.halted?'全天停牌':p.sealed===true?'收盘封板':p.sealed===false?'未封板':'待核验')+'</td><td>'+(p.height==null?'—':p.height)+'板</td><td>'+esc(p.reason|| (p.exact?'链完整':'链起点待核验'))+'</td></tr>';}).join('')+'</tbody></table></div><details><summary>完整计算依据</summary><pre style="white-space:pre-wrap;max-height:320px;overflow:auto">'+esc(JSON.stringify(m,null,2))+'</pre></details></details>';}''')
s=s.replace("m.highest_previous+' / '+m.highest_live+'板'","(m.cycles||{}).cycle_highest+' / '+m.highest_live+'板'").replace("'前一完成日 / 当前在板'","'周期核心 / 当前在板'")
s=s.replace("'同题材接续候选':'同题材已有至少3个完成连板的核心，核心当前仍在板；本股主动封首/二板、低至少两个板位，近期不是旧高标。只是接续观察，不表示必然补涨或连板。',", "'断板补涨候选':'已建立至少5板且当时为最高标的核心，实际断板当日的同题材首板批次；跟踪后续强度，不提前确认补涨龙。',\n '监管接续候选':'最高标首次严重异动公告公开后的首个可交易日，本股同日首板且共享确认题材；保留原批次后续晋级，不等同断板。',\n '停牌接续候选':'最高标停牌核查可知节点当日的同题材首板批次；停牌不视为断板。',\n '周期最高标':'近5个交易日仍有封板的至少5板周期核心中，已完成高度最高；已核验停牌保留高度但不增长。',\n '周期核心观察':'最近5个交易日仍有封板记录，且本轮至少完成5板的周期锚点；与当日在交易高标分开。',\n '停牌核心观察':'有日期有效的全天停牌公告证据，保留停牌前真实成交日与已完成高度，不计入当日在板或晋级分母。',\n '伴生关系观察':'共享确认题材，首次连板启动与核心相距不超过2个交易日，至少2个完成日同步封板；仅为关系观察，不自动代表当前仍强。',\n '已披露严重异动':'焦点股票近期公开公告已披露严重异常波动；逐条列出时间和链接，不等于当前必然停牌。',")
p.write_text(s,encoding='utf-8')
